// ============ 我的：任务中心（待办） ============
/** 待办列表（首页角标与任务中心列表条数统一取该列表的真实总数，避免口径不一致） */
export function getTodoTaskList(params: Record<string, unknown> = {}): Promise<PageResult<Record<string, unknown>>> {
  return page('/v2.0/flowable/task/todoTaskList', params)
}

/** 任务计数（bug 6959）：首页待办角标取 todoNum 真实值，非列表 total。 */
export interface TaskCountResult {
  todoNum?: number | string
  finishedNum?: number | string
  myProcessNum?: number | string
}
export function getTaskCount(): Promise<TaskCountResult> {
  return detail<TaskCountResult>('/v2.0/flowable/task/taskCount')
}

// 待办数取 taskCount 的 todoNum 真实值（bug 6959）；列表仍取第一条真实待办用于文案。
// taskCount 失败/未配置时回退列表 total，保证角标始终有兜底数字。
const [noticeRow, taskPage, taskCount, studyRows, newsRows, bannerRows] = await Promise.all([
  request(async () => (await api.businessNoticePage({ pageNum: 1, pageSize: 1 })).rows[0] as Row | undefined, undefined).catch(() => undefined),
  request(async () => await api.getTodoTaskList({ pageNum: 1, pageSize: 1 }), { total: 0, rows: [] as Row[] }).catch(() => ({ total: 0, rows: [] as Row[] })),
  request(async () => await api.getTaskCount(), {} as api.TaskCountResult).catch(() => ({} as api.TaskCountResult)),
  request(async () => rowsOrEmpty((await api.articlePage({ type: '1', pageNum: 1, pageSize: 2 })).rows), [] as Row[]).catch(() => [] as Row[]),
  request(async () => rowsOrEmpty((await api.articlePage({ pageNum: 1, pageSize: 3 })).rows), [] as Row[]).catch(() => [] as Row[]),
  request(async () => rowsOrEmpty((await api.getBannerList({ pageNum: 1, pageSize: 1 })).rows), [] as Row[]).catch(() => [] as Row[]),
])

